<?php $title="Schedule Test Ride";require "includes/header.php";$cs=$conn->query("SELECT id,name FROM customers");$bs=$conn->query("SELECT id,name FROM bicycles");if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO test_rides(customer_id,bicycle_id,ride_date,ride_time,status) VALUES(?,?,?,?,?)");$c=(int)$_POST["customer_id"];$b=(int)$_POST["bicycle_id"];$s->bind_param("iisss",$c,$b,$_POST["ride_date"],$_POST["ride_time"],$_POST["status"]);$s->execute();go("test_rides.php");}?><div class="card"><h2>Schedule Test Ride</h2><form method="post"><label>Customer</label><select name="customer_id"><?php while($x=$cs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=e($x["name"])?></option><?php endwhile;?></select><label>Bicycle</label><select name="bicycle_id"><?php while($x=$bs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=e($x["name"])?></option><?php endwhile;?></select><label>Date</label><input type="date" name="ride_date" value="<?=date("Y-m-d")?>"><label>Time</label><input type="time" name="ride_time"><label>Status</label><select name="status"><option>Booked</option><option>Completed</option><option>Cancelled</option></select><button class="btn primary">Book Ride</button></form></div><?php require "includes/footer.php";?>